//! Differential receipts are generated by the host with the pinned test oracle.
//! This standalone SDK test has no Node or application dependency.
use maru_diagram_engine::validate_json;
use serde::Deserialize;
use std::collections::{HashMap, HashSet};

#[derive(Deserialize)]
struct Corpus {
    rules: HashMap<String, Vec<Rule>>,
    cases: Vec<Case>,
}
#[derive(Deserialize)]
struct Rule {
    rule: String,
    code: String,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    id: String,
    diagram_type: String,
    rule: String,
    origin: Origin,
    comparison: Comparison,
}
#[derive(Deserialize)]
struct Origin {
    kind: String,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Comparison {
    input_json: String,
    accepted: bool,
    equivalent_codes: Vec<String>,
    current_scope: Scope,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Scope {
    kind: String,
    reason_id: Option<String>,
    reason: Option<String>,
}

#[test]
fn pinned_corpus_acceptance_and_equivalent_rejections_match_document_scope() {
    let corpus: Corpus = serde_json::from_str(include_str!("../testdata/parity.json")).unwrap();
    let mut supported_types = HashSet::new();
    let mut failures = Vec::new();
    for case in &corpus.cases {
        let report = validate_json(&case.comparison.input_json);
        assert_eq!(
            report.api_version, 1,
            "{} changed the API envelope",
            case.id
        );
        if report.ok != case.comparison.accepted {
            failures.push(format!(
                "{} ({}): expected accepted={}, got {:?}",
                case.id,
                case.comparison.current_scope.kind,
                case.comparison.accepted,
                report.diagnostics
            ));
        }
        if !case.comparison.accepted {
            assert!(
                !case.comparison.equivalent_codes.is_empty(),
                "{} has no equivalent rejection mapping",
                case.id
            );
            if !report
                .diagnostics
                .iter()
                .any(|diagnostic| case.comparison.equivalent_codes.contains(&diagnostic.code))
            {
                failures.push(format!(
                    "{}: expected one of {:?}, got {:?}",
                    case.id, case.comparison.equivalent_codes, report.diagnostics
                ));
            }
        }
        for diagnostic in &report.diagnostics {
            assert!(!diagnostic.code.is_empty(), "{} has an empty code", case.id);
            assert!(
                !diagnostic.path.is_empty(),
                "{} has an empty JSON path",
                case.id
            );
            assert!(!diagnostic.rule.is_empty(), "{} has an empty rule", case.id);
            assert!(!diagnostic.message.is_empty(), "{} has no cause", case.id);
            assert!(!diagnostic.fix.is_empty(), "{} has no next step", case.id);
        }
        if case.comparison.current_scope.kind != "document-validity" {
            assert!(
                case.comparison
                    .current_scope
                    .reason_id
                    .as_ref()
                    .is_some_and(|reason| !reason.is_empty()),
                "{} has an unnamed scope difference",
                case.id
            );
            assert!(
                case.comparison
                    .current_scope
                    .reason
                    .as_ref()
                    .is_some_and(|reason| !reason.is_empty()),
                "{} has no scope reason",
                case.id
            );
        }
        if case.comparison.current_scope.kind == "document-validity" {
            supported_types.insert(case.diagram_type.as_str());
        }
    }
    assert!(
        failures.is_empty(),
        "Differential counterexamples:\n{}",
        failures.join("\n")
    );
    assert_eq!(
        supported_types.len(),
        5,
        "all five supported types need current-scope cases"
    );
}

#[test]
fn every_declared_rule_has_a_generated_case_and_a_namespaced_code() {
    let corpus: Corpus = serde_json::from_str(include_str!("../testdata/parity.json")).unwrap();
    assert_eq!(corpus.rules.len(), 5);
    for (kind, rules) in &corpus.rules {
        for rule in rules {
            assert!(
                rule.code.starts_with(&format!("{kind}/")) || rule.code == "document/diagram-type",
                "unnamespaced code {}",
                rule.code
            );
            assert!(
                corpus.cases.iter().any(|case| case.diagram_type == *kind
                    && case.rule == rule.rule
                    && case.origin.kind == "synthetic-generated"
                    && !case.comparison.accepted
                    && case.comparison.equivalent_codes.contains(&rule.code)),
                "{kind}/{} has no generated per-type case",
                rule.rule
            );
        }
    }
}
